(()=>{
const mappedSymbol=s=>({'NSE:NIFTY50-INDEX':'NSE:NIFTY','NSE:NIFTYBANK-INDEX':'NSE:BANKNIFTY','BSE:SENSEX-INDEX':'BSE:SENSEX'})[s]||(/^(NSE|BSE):[A-Z0-9&._-]+-EQ$/.test(s)?s.slice(0,-3):null);
const directSymbol=s=>typeof s==='string'&&/^[A-Z0-9_]{2,20}:[A-Z0-9&._!\/-]{1,70}$/.test(s);
const css=`.radar-tv-panel{min-width:0;background:#fff;border:1px solid #e0e6ef;border-radius:12px;padding:12px}.radar-tv-header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:12px}.radar-tv-header h3{margin:0;font:600 18px system-ui;color:#26344b}.radar-tv-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.radar-tv-actions a{font:500 14px system-ui;color:#594281}.radar-tv-panel button{background:#fff;color:#334155;border:1px solid #cbd5e1;border-radius:8px;padding:9px 13px;cursor:pointer}.radar-tv-canvas{height:clamp(480px,72vh,900px);min-height:480px;width:100%}.radar-tv-status{font:14px/1.5 system-ui;color:#5c6679;margin:8px 0}.radar-tv-status:empty{display:none}.radar-tv-status[data-error=true]{color:#9f3544}.radar-tv-manual{display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin:12px 0}.radar-tv-manual[hidden]{display:none}.radar-tv-manual label{display:grid;gap:6px;font:14px system-ui}.radar-tv-manual input{padding:10px;border:1px solid #cbd5e1;border-radius:8px}.radar-tv-panel.is-expanded{position:fixed;inset:10px;z-index:10000;overflow:auto;box-sizing:border-box;box-shadow:0 0 0 12px #fff}.radar-tv-panel.is-expanded .radar-tv-canvas{height:calc(100dvh - 110px);min-height:320px}@media(max-width:600px){.radar-tv-panel{padding:8px}.radar-tv-header{align-items:flex-start}.radar-tv-canvas{height:65vh;min-height:460px}.radar-tv-panel.is-expanded{inset:4px}.radar-tv-panel.is-expanded .radar-tv-canvas{height:calc(100dvh - 150px)}}`;
window.RadarTradingView={mappedSymbol,mount(host,{symbol,allowSymbolChange=true,tradingViewSymbol=false}={}){
 if(!document.getElementById('radar-tv-style')){const style=document.createElement('style');style.id='radar-tv-style';style.textContent=css;(document.head||document.body).append(style)}
 host.innerHTML='<section class="radar-tv-panel"><header class="radar-tv-header"><h3>TradingView chart</h3><div class="radar-tv-actions"><a data-tv-open href="https://www.tradingview.com/chart/" target="_blank" rel="noopener noreferrer">Open TradingView ↗</a><button data-tv-expand type="button" aria-pressed="false">Expand chart</button><button data-tv-retry type="button" hidden>Retry chart</button></div></header><p data-tv-help class="radar-tv-status">If TradingView says a symbol is only available on TradingView, use the stock link above. Reloading cannot unlock restricted data.</p><p data-tv-status class="radar-tv-status" role="status"></p><form data-tv-manual class="radar-tv-manual" hidden><label>TradingView symbol<input data-tv-symbol maxlength="92" placeholder="NSE:RELIANCE" autocomplete="off"></label><button type="submit">Open chart</button></form><div data-tv-canvas class="radar-tv-canvas"></div></section>';
 const $=name=>host.querySelector('[data-tv-'+name+']'),panel=host.querySelector('.radar-tv-panel');let active=true,generation=0,deadline=null,observer=null,script=null,expanded=false,overflow=null,current=tradingViewSymbol&&directSymbol(symbol)?symbol:mappedSymbol(symbol),previousFocus=null;
 const status=(message,error=false)=>{$('status').textContent=message;$('status').dataset.error=String(error);$('retry').hidden=!error||!current};
 function clear(){generation++;if(deadline!==null)clearTimeout(deadline);deadline=null;observer?.disconnect();observer=null;if(script){script.onload=null;script.onerror=null}script=null;$('canvas').replaceChildren()}
 function render(){clear();$('open').href='https://www.tradingview.com/chart/'+(current?'?symbol='+encodeURIComponent(current):'');$('open').textContent=current?'Open '+current+' on TradingView ↗':'Open TradingView ↗';$('help').hidden=!current;if(!current){$('manual').hidden=false;status('Select this contract on TradingView, or enter its exact TradingView symbol below.');return}
 $('manual').hidden=true;$('retry').hidden=true;status('Loading TradingView…');const token=generation,container=document.createElement('div'),body=document.createElement('div'),credit=document.createElement('div'),link=document.createElement('a');container.className='tradingview-widget-container';container.style.cssText='height:100%;width:100%';body.className='tradingview-widget-container__widget';body.style.cssText='height:calc(100% - 32px);width:100%';credit.className='tradingview-widget-copyright';link.href='https://www.tradingview.com/';link.target='_blank';link.rel='noopener noreferrer';link.textContent='Charts by TradingView';credit.append(link);
 // The widget owns chart search and tools. It is deliberately independent of any order ticket.
 script=document.createElement('script');script.src='https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js';script.type='text/javascript';script.async=true;script.textContent=JSON.stringify({autosize:true,symbol:current,interval:'60',timezone:'Asia/Kolkata',theme:'light',style:'1',locale:'en',allow_symbol_change:allowSymbolChange,hide_top_toolbar:false,hide_side_toolbar:false,save_image:true,calendar:false,support_host:'https://www.tradingview.com'});
 const inspect=()=>{if(!active||token!==generation)return;const frame=$('canvas').querySelector('iframe');if(frame){frame.title='TradingView interactive chart';status('');if(deadline!==null)clearTimeout(deadline);deadline=null;observer?.disconnect();observer=null}};
 script.onload=inspect;script.onerror=()=>{if(active&&token===generation)status('TradingView could not load. Retry the chart or open TradingView.',true)};
 container.append(body,credit,script);$('canvas').append(container);
 if(typeof MutationObserver!=='undefined'){observer=new MutationObserver(inspect);observer.observe($('canvas'),{childList:true,subtree:true})}
 if(typeof setTimeout==='function')deadline=setTimeout(()=>{if(!active||token!==generation)return;if($('canvas').querySelector('iframe'))inspect();else status('TradingView is taking longer to load. Retry or open TradingView.',true)},15000);
 // A cross-origin iframe existing does not prove that its market data is available.
 }
 function expand(next){expanded=next;panel.classList.toggle('is-expanded',next);$('expand').textContent=next?'Exit expanded chart':'Expand chart';$('expand').setAttribute('aria-pressed',String(next));if(next){previousFocus=document.activeElement;overflow=document.body.style.overflow;document.body.style.overflow='hidden';$('expand').focus?.()}else if(overflow!==null){document.body.style.overflow=overflow;overflow=null;previousFocus?.focus?.()}}
 $('expand').onclick=()=>expand(!expanded);$('retry').onclick=render;$('manual').onsubmit=e=>{e.preventDefault();const input=$('symbol').value.trim().toUpperCase();if(!directSymbol(input)){status('Enter an exchange and symbol, for example NSE:RELIANCE.',true);return}current=input;render()};
 // The link names its exact application-selected symbol; private iframe search changes cannot update it.
 const key=e=>{if(e.key==='Escape'&&expanded)expand(false)};document.addEventListener('keydown',key);render();
 return ()=>{if(!active)return;active=false;expand(false);clear();document.removeEventListener('keydown',key);$('expand').onclick=null;$('retry').onclick=null;$('manual').onsubmit=null};
}};
window.DhanMarketChart={mount(host,{symbol}={}){return window.RadarTradingView.mount(host,{symbol,allowSymbolChange:true})}};
})();
